#include <iostream>
using namespace std;

int main() {
    int x;
    cin >> x;
    cout << "第 3 位: " << ((x >> 2) & 1) << endl;
    cout << "设置第 3 位为 1: " << (x | (1 << 2)) << endl;
    cout << "设置第 3 位为 0: " << (x & ~(1 << 2)) << endl;
    cout << "二进制: ";
    for (int i = 31; i >= 0; i--) cout << ((x >> i) & 1);
    cout << endl;
    cout << "是否为 2 的幂: " << (x > 0 && (x & (x - 1)) == 0) << endl;
    return 0;
}

#include <iostream>
#include <bitset>
using namespace std;

int main() {
    int S = 0;
    S |= (1 << 2); S |= (1 << 5); S |= (1 << 7);
    cout << "集合 S: " << S << endl;
    cout << "元素 3 存在? " << ((S >> 3) & 1) << endl;
    cout << "元素 5 存在? " << ((S >> 5) & 1) << endl;
    S &= ~(1 << 5);
    cout << "删除元素 5 后: " << S << endl;
    int T = (1 << 1) | (1 << 3) | (1 << 5);
    cout << "并集 S|T: " << (S | T) << endl;
    cout << "交集 S&T: " << (S & T) << endl;
    for (int i = 0; i < 10; i++)
        if ((S >> i) & 1) cout << i << " ";
    cout << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n = 3, a[] = {1, 2, 3};
    cout << "所有子集:" << endl;
    for (int mask = 0; mask < (1 << n); mask++) {
        for (int i = 0; i < n; i++)
            if ((mask >> i) & 1) cout << a[i] << " ";
        cout << endl;
    }
    cout << "子集的子集 (mask=5=101):" << endl;
    int mask = 5;
    for (int s = mask; s; s = (s - 1) & mask) {
        for (int i = 0; i < n; i++)
            if ((s >> i) & 1) cout << a[i] << " ";
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n = 4, dist[4][4] = {{0,2,3,1},{2,0,4,5},{3,4,0,6},{1,5,6,0}};
    const int INF = 1e9;
    int dp[1 << 4][4];
    for (int mask = 0; mask < (1 << n); mask++)
        for (int i = 0; i < n; i++) dp[mask][i] = INF;
    dp[1][0] = 0;
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int i = 0; i < n; i++) {
            if (!(mask & (1 << i))) continue;
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) continue;
                dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + dist[i][j]);
            }
        }
    }
    int ans = INF;
    for (int i = 1; i < n; i++) ans = min(ans, dp[(1 << n) - 1][i] + dist[i][0]);
    cout << ans << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, a[100005], xorSum = 0, a1 = 0, a2 = 0;
    cin >> n;
    for (int i = 0; i < n; i++) { cin >> a[i]; xorSum ^= a[i]; }
    int k = 0;
    while ((xorSum >> k) & 1 == 0) k++;
    for (int i = 0; i < n; i++) {
        if ((a[i] >> k) & 1) a1 ^= a[i];
        else a2 ^= a[i];
    }
    cout << a1 << " " << a2 << endl;
    return 0;
}

#include <iostream>
using namespace std;

int lowbit(int x) {
    return x & (-x);
}

int main() {
    int mask = 10;  // 1010
    cout << "lowbit(10) = " << lowbit(10) << endl;
    cout << "子集的子集:" << endl;
    for (int s = mask; s; s -= lowbit(s)) {
        int p = lowbit(s) >> 1;
        while (p) p >>= 1, cout << 0;
        for (int i = s; i; i -= lowbit(i)) cout << 1;
        cout << endl;
    }
    return 0;
}

units.explanation:
SOS DP（Sum Over Subsets DP）：高效计算每个子集的某种聚合值，如子集和、子集 AND、子集 OR 等。

核心思想：
给定函数 f[mask]，计算 g[mask] = sum{f[s] | s 是 mask 的子集}
直接暴力是 O(n * 2^n)，SOS DP 优化到 O(n * 2^n)

算法流程（FMT - Fast Möbius Transform）：
for (int i = 0; i < n; i++)
    for (int mask = 0; mask < (1 << n); mask++)
        if (mask & (1 << i))
            dp[mask] += dp[mask ^ (1 << i)];

原理：每轮考虑第 i 位，让所有包含第 i 位的 mask 从不包含第 i 位的子集继承。

应用：
1. 子集和：g[mask] = sum{f[s] | s ⊆ mask}
2. 子集 OR：g[mask] = OR{f[s] | s ⊆ mask}
3. 子集 AND：g[mask] = AND{f[s] | s ⊆ mask}
4. 快速莫比乌斯变换（FMT）和卷积

时间复杂度：O(n * 2^n)
空间复杂度：O(2^n)

