#include <iostream>
using namespace std;

int main() {
    int n = 3;
    int f[1 << 3] = {1, 2, 3, 4, 5, 6, 7, 8};
    int dp[1 << 3];
    for (int mask = 0; mask < (1 << n); mask++) dp[mask] = f[mask];
    for (int i = 0; i < n; i++) {
        for (int mask = 0; mask < (1 << n); mask++) {
            if (mask & (1 << i)) dp[mask] += dp[mask ^ (1 << i)];
        }
    }
    for (int mask = 0; mask < (1 << n); mask++)
        cout << mask << ": " << dp[mask] << endl;
    return 0;
}
